# Imports
from dataclasses import dataclass
from collections import ChainMap
from typing import Optional

# Package Imports
from gmdkit.utils.enums import GameObjectType, ZLayer, ObjectPropertyFlag
from gmdkit.serialization.classes import FieldInterface, InterfaceMetaclass


@dataclass(frozen=True, slots=True)
class ObjectProperties:
    object_id: int
    frame: str
    object_type: GameObjectType = GameObjectType.SOLID
    width: Optional[float] = None
    height: Optional[float] = None
    width_scale: float = 1.0
    height_scale: float = 1.0
    width_from_height: bool = False
    height_from_width: bool = False
    radius: Optional[float] = 0
    radius_scale: float = 1.0
    box_offset_x: float = 0
    box_offset_y: float = 0
    z_layer: ZLayer = ZLayer.DEFAULT
    z_order: int = 2
    main_color: int = 1004
    detail_color: Optional[int] = None
    flags: ObjectPropertyFlag = ObjectPropertyFlag(0)
    sprite_width: Optional[float] = None
    sprite_height: Optional[float] = None
    editor_keys: str = ""

    @property
    def hitbox_width(self) -> Optional[float]:
        width = self.width
        if width is None:
            width = self.sprite_height if self.width_from_height else self.sprite_width
            if width is None:
                return None
        return round(width * self.width_scale, 4)

    @property
    def hitbox_height(self) -> Optional[float]:
        height = self.height
        if height is None:
            height = self.sprite_width if self.height_from_width else self.sprite_height
            if height is None:
                return None
        return round(height * self.height_scale, 4)

    @property
    def hitbox_radius(self) -> Optional[float]:
        radius = self.radius
        if radius is None:
            if self.sprite_width is None:
                return None
            radius = self.sprite_width
        return round(radius * self.radius_scale, 4)

    @property
    def is_trigger(self) -> bool:
        return ObjectPropertyFlag.IS_TRIGGER in self.flags

    @property
    def can_be_controlled(self) -> bool:
        return ObjectPropertyFlag.CAN_BE_CONTROLLED in self.flags

    @property
    def is_start_pos(self) -> bool:
        return ObjectPropertyFlag.IS_START_POS in self.flags

    @property
    def is_invisible(self) -> bool:
        return ObjectPropertyFlag.IS_INVISIBLE in self.flags

    @property
    def intrinsic_dont_fade(self) -> bool:
        return ObjectPropertyFlag.INTRINSIC_DONT_FADE in self.flags

    @property
    def solid_color_block(self) -> bool:
        return ObjectPropertyFlag.SOLID_COLOR_BLOCK in self.flags

    @property
    def invisible_block(self) -> bool:
        return ObjectPropertyFlag.INVISIBLE_BLOCK in self.flags

    @property
    def slope_is_hazard(self) -> bool:
        return ObjectPropertyFlag.SLOPE_IS_HAZARD in self.flags

    @property
    def use_object_rect(self) -> bool:
        return ObjectPropertyFlag.USE_OBJECT_RECT in self.flags

    @property
    def uses_audio_scale(self) -> bool:
        return ObjectPropertyFlag.USES_AUDIO_SCALE in self.flags

    @property
    def fixed_z_layer(self) -> bool:
        return ObjectPropertyFlag.FIXED_Z_LAYER in self.flags

    @property
    def not_colorable(self) -> bool:
        return ObjectPropertyFlag.NOT_COLORABLE in self.flags


class FrameLoaderMetaclass(InterfaceMetaclass):

    _FRAME_REGISTRY: dict
    _FRAME_CHAIN: ChainMap

    def __new__(mcls, name, bases, namespace, **kwargs):
        cls = super().__new__(mcls, name, bases, namespace, **kwargs)
        cls._FRAME_REGISTRY = cls.__dict__.get("_FRAME_REGISTRY", {})
        cls._FRAME_CHAIN = ChainMap(*(
            klass.__dict__["_FRAME_REGISTRY"]
            for klass in cls.__mro__
            if "_FRAME_REGISTRY" in klass.__dict__
        ))
        return cls

    def register_frame(cls, object_id, props: ObjectProperties) -> ObjectProperties:
        cls._FRAME_REGISTRY[object_id] = props
        return props

    def get_frame(cls, object_id) -> Optional[ObjectProperties]:
        return cls._FRAME_CHAIN.get(object_id)

    def get_frame_ids(cls) -> set:
        return set(cls._FRAME_CHAIN)


class FrameInterface(FieldInterface, metaclass=FrameLoaderMetaclass):

    @property
    def frame_properties(self) -> Optional[ObjectProperties]:
        return type(self).get_frame(self.current_id)

    def get_frame_property(self, name: str, default=None):
        props = self.frame_properties
        return default if props is None else getattr(props, name)


def frame_default(attribute: str, fallback=0):
    def factory(owner=None):
        if owner is None:
            return fallback
        props = FrameInterface.get_frame(owner.current_id)
        value = None if props is None else getattr(props, attribute)
        return fallback if value is None else value
    return factory


def register(
        object_id: int,
        frame: str,
        *,
        object_type: GameObjectType = GameObjectType.SOLID,
        width: Optional[float] = None,
        height: Optional[float] = None,
        width_scale: float = 1.0,
        height_scale: float = 1.0,
        width_from_height: bool = False,
        height_from_width: bool = False,
        radius: Optional[float] = 0,
        radius_scale: float = 1.0,
        box_offset_x: float = 0,
        box_offset_y: float = 0,
        z_layer: ZLayer = ZLayer.DEFAULT,
        z_order: int = 2,
        main_color: int = 1004,
        detail_color: Optional[int] = None,
        flags: ObjectPropertyFlag = ObjectPropertyFlag(0),
        sprite_width: Optional[float] = None,
        sprite_height: Optional[float] = None,
        editor_keys: str = "",
        ) -> ObjectProperties:
    return FrameInterface.register_frame(object_id, ObjectProperties(
        object_id=object_id,
        frame=frame,
        object_type=object_type,
        width=width,
        height=height,
        width_scale=width_scale,
        height_scale=height_scale,
        width_from_height=width_from_height,
        height_from_width=height_from_width,
        radius=radius,
        radius_scale=radius_scale,
        box_offset_x=box_offset_x,
        box_offset_y=box_offset_y,
        z_layer=z_layer,
        z_order=z_order,
        main_color=main_color,
        detail_color=detail_color,
        flags=flags,
        sprite_width=sprite_width,
        sprite_height=sprite_height,
        editor_keys=editor_keys,
    ))


